-- COUNT(*) over a rowid range on a multi-level tree with gaps: the count
-- walk stops at the first child past the range's end and counts a leaf
-- with two binary searches (it used to read every leaf of the table for
-- `rowid <= x`: the torture S16 readers' 82 s vs SQLite's 43 s).
CREATE TABLE t (id INTEGER PRIMARY KEY, v TEXT);
WITH RECURSIVE c(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM c WHERE i < 30000) INSERT INTO t SELECT i * 3, 'x' || i FROM c;
DELETE FROM t WHERE id % 7 = 0;
INSERT INTO t VALUES (-9223372036854775808, 'min'), (9223372036854775807, 'max'), (-5, 'neg'), (0, 'zero');
